import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const compare = (a, b) => a < b ? -1 : a > b ? 1 : 0;
const validId = value => typeof value === 'string' && value.length > 0;

export function planJobs(spec) {
  if (!Array.isArray(spec)) throw new Error('Expected an array of jobs');
  const jobs = new Map();
  for (const job of spec) {
    if (job === null || typeof job !== 'object' || Array.isArray(job) ||
        !validId(job.id) || !Array.isArray(job.deps) ||
        !['pending', 'succeeded', 'failed'].includes(job.state)) {
      throw new Error('Malformed job');
    }
    if (jobs.has(job.id)) throw new Error('Duplicate job ID');
    const deps = new Set();
    for (const dep of job.deps) {
      if (!validId(dep) || deps.has(dep)) throw new Error('Invalid or duplicate dependency');
      deps.add(dep);
    }
    jobs.set(job.id, { id: job.id, deps, state: job.state, children: [], remaining: deps.size, causes: new Set() });
  }
  for (const job of jobs.values()) {
    for (const dep of job.deps) {
      if (!jobs.has(dep)) throw new Error('Unknown dependency');
      jobs.get(dep).children.push(job.id);
    }
  }

  // Keep the frontier sorted, inserting newly available jobs before choosing again.
  const frontier = [...jobs.values()].filter(job => job.remaining === 0)
    .map(job => job.id).sort(compare);
  const fullOrder = [];
  while (frontier.length) {
    const id = frontier.shift();
    const job = jobs.get(id);
    fullOrder.push(id);
    for (const childId of job.children) {
      const child = jobs.get(childId);
      // Propagate ancestry regardless of either endpoint's state.
      for (const cause of job.causes) child.causes.add(cause);
      if (job.state === 'failed') child.causes.add(id);
      if (--child.remaining === 0) {
        let low = 0, high = frontier.length;
        while (low < high) {
          const mid = (low + high) >>> 1;
          if (compare(frontier[mid], childId) < 0) low = mid + 1;
          else high = mid;
        }
        frontier.splice(low, 0, childId);
      }
    }
  }
  if (fullOrder.length !== jobs.size) throw new Error('Dependency cycle');

  const order = [], ready = [], blocked = [];
  for (const id of fullOrder) {
    const job = jobs.get(id);
    if (job.state !== 'pending') continue;
    if (job.causes.size) {
      blocked.push({ id, causes: [...job.causes].sort(compare) });
    } else {
      order.push(id);
      if ([...job.deps].every(dep => jobs.get(dep).state === 'succeeded')) ready.push(id);
    }
  }
  ready.sort(compare);
  blocked.sort((a, b) => compare(a.id, b.id));
  return { order, ready, blocked };
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  try {
    if (process.argv.length !== 3) throw new Error('Usage: node job-plan.js SPECFILE');
    const plan = planJobs(JSON.parse(readFileSync(process.argv[2], 'utf8')));
    process.stdout.write(JSON.stringify(plan) + '\n');
  } catch (error) {
    process.stderr.write(`job-plan: ${error.message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { planJobs } from '../job-plan.js';

const job = (id, deps = [], state = 'pending') => ({ id, deps, state });

test('validates required fields and every graph component', () => {
  const invalid = [null, {}, 'jobs', [null], [[]], [{}],
    [{ id: '', deps: [], state: 'pending' }],
    [{ id: 1, deps: [], state: 'pending' }],
    [{ id: 'x', state: 'pending' }],
    [{ id: 'x', deps: 'y', state: 'pending' }],
    [{ id: 'x', deps: [] }],
    [{ id: 'x', deps: [], state: 'Pending' }],
    [job('x', [''])], [job('x', [1])], [job('x', ['y'])],
    [job('x'), job('x')], [job('x', ['y', 'y']), job('y')],
    [job('x', ['x'], 'succeeded')],
    [job('p'), job('x', ['y'], 'failed'), job('y', ['x'], 'succeeded')]];
  for (const spec of invalid) assert.throws(() => planJobs(spec), Error);
});

test('uses full-graph Kahn ordering, not pending-only ordering', () => {
  const spec = [job('a', ['z']), job('b'), job('z', [], 'succeeded')];
  assert.deepEqual(planJobs(spec), { order: ['b', 'a'], ready: ['a', 'b'], blocked: [] });
  assert.deepEqual(planJobs([...spec].reverse()), planJobs(spec));
  assert.deepEqual(planJobs([job('a'), job('b', ['a'])]), {
    order: ['a', 'b'], ready: ['a'], blocked: [],
  });
});

test('collects all failed ancestors through completed intermediates', () => {
  const spec = [job('z', [], 'failed'), job('a', ['z'], 'failed'),
    job('s', ['a'], 'succeeded'), job('p', ['s', 'z']), job('q', ['p']),
    job('r', ['s']), job('ok', [], 'succeeded'), job('next', ['ok'])];
  assert.deepEqual(planJobs(spec), {
    order: ['next'], ready: ['next'], blocked: [
      { id: 'p', causes: ['a', 'z'] }, { id: 'q', causes: ['a', 'z'] },
      { id: 'r', causes: ['a', 'z'] },
    ],
  });
});

test('preserves exact IDs, ignores extras, and does not mutate frozen inputs', () => {
  const ids = ['é', 'Z', 'a', '😀', '\uE000', '__proto__', 'constructor', ' ', ' a '];
  const sorted = [...ids].sort((a, b) => a < b ? -1 : a > b ? 1 : 0);
  const spec = Object.freeze(ids.map(id => Object.freeze({
    id, deps: Object.freeze([]), state: 'pending', extra: { ignored: true },
  })));
  assert.deepEqual(planJobs(spec), { order: sorted, ready: sorted, blocked: [] });
  assert.deepEqual(planJobs([job('__proto__', [], 'failed'), job('constructor', ['__proto__'])]), {
    order: [], ready: [], blocked: [{ id: 'constructor', causes: ['__proto__'] }],
  });
});

test('CLI success, failures and inert module import', () => {
  const cli = fileURLToPath(new URL('../job-plan.js', import.meta.url));
  const dir = mkdtempSync(join(tmpdir(), 'job-plan-'));
  const run = args => spawnSync(process.execPath, [cli, ...args], { encoding: 'utf8' });
  const fails = args => {
    const result = run(args);
    assert.ifError(result.error);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  };
  try {
    const good = join(dir, 'valid unicode é.json');
    writeFileSync(good, JSON.stringify([job('é')]));
    const result = run([good]);
    assert.ifError(result.error);
    assert.equal(result.status, 0);
    assert.equal(result.stdout, JSON.stringify({ order: ['é'], ready: ['é'], blocked: [] }) + '\n');
    assert.equal(result.stderr, '');
    fails([]);
    fails([good, good]);
    fails([join(dir, 'absent.json')]);
    const bad = join(dir, 'bad.json');
    for (const content of ['{', '{}', JSON.stringify([job('x', ['x'])]), JSON.stringify([job('x', ['absent'])])]) {
      writeFileSync(bad, content);
      fails([bad]);
    }
    const imported = spawnSync(process.execPath,
      ['--input-type=module', '-e', `await import(${JSON.stringify(new URL('../job-plan.js', import.meta.url).href)})`],
      { encoding: 'utf8' });
    assert.ifError(imported.error);
    assert.equal(imported.status, 0);
    assert.equal(imported.stdout, '');
    assert.equal(imported.stderr, '');
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

